import {stageHTML,mountStage,showSplash} from './studio-experience.js';
const $ = (s, root = document) => root.querySelector(s);
const icons = {
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>', left:'<path d="M19 12H5m6 6-6-6 6-6"/>', check:'<path d="m5 12 4 4L19 6"/>',
  cube:'<path d="m12 3 9 5v8l-9 5-9-5V8l9-5Zm0 10v8M3 8l9 5 9-5M7.5 5.5l9 5"/>', image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 16 5-5 4 4 4-5 5 6"/>',
  external:'<path d="M8 5h11v11M19 5 5 19"/>', shield:'<path d="M12 3 4 6v6c0 4 8 9 8 9s8-5 8-9V6l-8-3Z"/><path d="m8 12 3 3 5-6"/>',
  delivery:'<path d="M3 6h11v11H3zM14 10h4l3 4v3h-7"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/>',
  file:'<path d="M14 3H5v18h14V8l-5-5ZM14 3v5h5M8 12h8M8 16h6"/>', lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7v.1"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', compare:'<path d="M5 3v18M19 3v18M5 7h10m-3-3 3 3-3 3M19 17H9m3-3-3 3 3 3"/>',
  rotate:'<path d="M3 10a9 9 0 1 1 2 8M3 4v6h6"/>', plus:'<path d="M12 5v14M5 12h14"/>', minus:'<path d="M5 12h14"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>', edit:'<path d="m16 3 5 5L9 20l-6 1 1-6L16 3ZM13 6l5 5"/>',
  conveyor:'<path d="M2 17h19v5H2zM2 12h5l7 5M7 12l4-8 4 2-4 9M11 4l-3-2M4 22v2m14-2v2"/><path d="m10 7 4 2m-6 1 4 2M5 19h2m3 0h2m3 0h2"/>',
  probe:'<path d="M9 2h8v4H9zM11 6v10h4V6M12 16v5l-3 2m4-2 3 2M4 25h18M3 9h4m10 0h4M5 7v4m14-4v4"/>',
  coolant:'<path d="M3 22h20M6 22V11h6v11M5 11h8V7H5zM9 7V3h9v7M17 12c-5 6-1 8 1 8s6-2 1-8Z"/><path d="M16 23v3m4-3v3M3 27h23"/>',
  rotary:'<ellipse cx="13" cy="13" rx="10" ry="5"/><path d="M3 13v7c0 6 20 6 20 0v-7M7 24v3m12-3v3M5 27h17"/><ellipse cx="13" cy="13" rx="4" ry="2"/><path d="m8 5 3-3 3 3m-3-3v5M20 4h4v4"/>',
  box:'<path d="m3 8 10-5 10 5v14l-10 5-10-5V8Zm0 0 10 5 10-5M13 13v14M8 5.5l10 5v6l-5 2"/>',
  ruler:'<path d="m3 19 16-16 6 6L9 25 3 19ZM16 6l3 3M12 10l2 2M8 14l3 3M4 18l2 2"/>'
};
const icon = (name, cls='') => `<svg class="${cls}" aria-hidden="true" viewBox="0 0 ${['conveyor','probe','coolant','rotary','box','ruler'].includes(name)?'28 30':'24 24'}">${icons[name]||icons.cube}</svg>`;
const money = n => '$'+Number(n).toLocaleString('en-US');
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stepNames = ['Select machine','Accessories','Your details','Review & download'];
const stepSub = ['Find your perfect fit','Tailor your capabilities','Personalize your quotation','Your next chapter awaits'];
let data, sceneController, sceneGeneration=0, modalMachine, modalTab='specs', toastTimer, pdfBusy=false,preparedPdfUrl,modalSceneController;
let state={machine:'nv-1270',accessories:[],step:1,maxStep:1,filter:'all',view:'3d',details:{name:'',email:'',company:'',notes:''}};
let canSave=true;
try {
  const draft=JSON.parse(localStorage.getItem('nanya-studio-config')||'null');
  if(draft && typeof draft.machine==='string' && Array.isArray(draft.accessories)) Object.assign(state,{machine:draft.machine,accessories:draft.accessories});
  const details=JSON.parse(sessionStorage.getItem('nanya-studio-customer')||'null');
  if(details) for(const k of Object.keys(state.details)) if(typeof details[k]==='string') state.details[k]=details[k].slice(0,k==='notes'?2400:180);
} catch {canSave=false;}
try {
  const response=await fetch('data.json'); if(!response.ok)throw new Error('Configuration unavailable'); data=await response.json();
  if(!data.models.some(m=>m.id===state.machine))state.machine='nv-1270';
  state.accessories=state.accessories.filter(id=>data.accessories.some(a=>a.id===id));
  const params=new URLSearchParams(location.search); if(data.models.some(m=>m.id===params.get('machine')))state.machine=params.get('machine');
  render(); $('#year').textContent=new Date().getFullYear();
  let seenIntro=false;try{seenIntro=sessionStorage.getItem('nanya-studio-intro-v2')==='seen';}catch{}if(!seenIntro)openIntro();
} catch(error) {$('#main-column').innerHTML='<div class="section-panel"><h2>Let’s reconnect.</h2><p>Machine data could not be loaded. Please refresh to reopen your quotation studio.</p><button class="secondary-button" onclick="location.reload()">Reload studio</button></div>';}
function model(){return data.models.find(m=>m.id===state.machine);}
function accessoryPrice(a){return Object.hasOwn(data.prices[state.machine]||{},a.id)?data.prices[state.machine][a.id]:a.price;}
function selectedAccessories(){return data.accessories.filter(a=>state.accessories.includes(a.id));}
function totals(){let accessories=0,onRequest=false;for(const a of selectedAccessories()){let p=accessoryPrice(a);if(p===null)onRequest=true;else accessories+=p;}return{accessories,total:model().price+accessories,onRequest};}
function save(){try{localStorage.setItem('nanya-studio-config',JSON.stringify({machine:state.machine,accessories:state.accessories}));sessionStorage.setItem('nanya-studio-customer',JSON.stringify(state.details));$('#save-label').textContent='Draft saved';}catch{$('#save-label').textContent='Current session';}}
function quoteDates(){const d=new Date();const now=new Date(d.toLocaleString('en-US',{timeZone:'Asia/Karachi'}));const end=new Date(now);end.setDate(end.getDate()+30);const fmt=d=>d.toLocaleDateString('en-US',{day:'numeric',month:'short',year:'numeric'});return{date:fmt(now),valid:fmt(end),id:`NY${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}${String(now.getDate()).padStart(2,'0')}-${model().name}`};}
function render(){renderSteps();renderMain();renderSummary();}
function renderSteps(){ $('#stepper').innerHTML=stepNames.map((name,i)=>`<button class="step ${state.step===i+1?'current':state.step>i+1?'done':''}" data-action="step" data-step="${i+1}" ${i+1>state.maxStep?'disabled':''} ${state.step===i+1?'aria-current="step"':''}><span class="step-number">${state.step>i+1?icon('check'):String(i+1).padStart(2,'0')}</span><span><strong>${name}</strong><small>${stepSub[i]}</small></span>${i<3?icon('arrow','step-arrow'):''}</button>`).join('');}
function renderMain(){sceneGeneration++;if(sceneController){sceneController.dispose();sceneController=null;}const root=$('#main-column');root.innerHTML=state.step===1?machineScreen():state.step===2?accessoryScreen():state.step===3?customerScreen():reviewScreen();if(state.step===1){setupProductMotion();const list=$('#machine-list'),selected=$('.machine-card.selected');if(list&&selected)list.scrollLeft=selected.offsetLeft-list.offsetLeft-list.clientWidth/2+selected.clientWidth/2;setupScene();}}
function machineScreen(){const m=model();const list=data.models.filter(m=>state.filter==='all'||(state.filter==='compact'?m.series==='Compact Series':m.series!=='Compact Series'));return `
${stageHTML(m,state.view)}
<section aria-label="Machine collection"><div class="collection-header"><h2>Choose your machine <small>07 engineered possibilities</small></h2><div class="collection-arrows"><button data-action="scroll-left" aria-label="Previous machines">${icon('left')}</button><button data-action="scroll-right" aria-label="More machines">${icon('arrow')}</button></div></div>
 <div class="collection-controls"><div class="filters" role="group" aria-label="Filter machines">${[['all','All machines'],['compact','Compact series'],['performance','High performance']].map(([id,label])=>`<button class="filter ${state.filter===id?'active':''}" data-action="filter" data-filter="${id}" aria-pressed="${state.filter===id}">${label}</button>`).join('')}</div><button class="compare-link" data-action="compare">${icon('compare')} Compare models</button></div>
 <div class="machine-list" id="machine-list">${list.map(m=>`<button class="machine-card ${m.id===state.machine?'selected':''}" data-action="machine" data-machine="${m.id}" aria-label="Select ${m.name}, ${money(m.price)}" aria-pressed="${m.id===state.machine}"><span class="card-series">${m.series==='Compact Series'?'COMPACT SERIES':'PERFORMANCE SERIES'}</span><span class="card-check">${icon('check')}</span><img src="${m.image}" alt="" loading="lazy"><strong>${m.name}</strong><span class="card-meta">${m.travel[0]} × ${m.travel[1]} × ${m.travel[2]} mm travel</span><span class="card-price">${money(m.price)}<span>USD</span></span></button>`).join('')}</div>
 <p class="collection-note">${icon('info')} All models include MITSUBISHI M80A control, a 12,000 RPM spindle and a 24-tool automatic tool changer.</p></section>`;}
function modelStrip(){const m=model();return`<div class="selected-model-strip"><div><img src="${m.image}" alt=""><div><strong>${m.name}</strong><small>${m.travel.join(' × ')} mm travel · MITSUBISHI M80A</small></div></div><button data-action="step" data-step="1">Change machine ↗</button></div>`;}
function accessoryScreen(){return`<section class="section-panel"><div class="section-label">02 / ACCESSORIES</div><h2 class="section-title">Built around your process.</h2><p class="section-description">Add the capabilities your work demands. Your quotation updates as you go.</p>${modelStrip()}<div class="accessory-grid">${data.accessories.map(a=>{const selected=state.accessories.includes(a.id);const p=accessoryPrice(a);return`<button class="accessory-card ${selected?'selected':''}" data-action="accessory" data-accessory="${a.id}" aria-pressed="${selected}" aria-label="${esc(a.name)}, ${p===null?'price on request':money(p)}"><span class="card-check">${icon('check')}</span>${icon(a.icon,'accessory-art')}<span class="accessory-category">${a.category}</span><strong>${a.name}</strong><p>${a.description}</p><span class="accessory-price">${p===null?'On request':money(p)}${p!==null?'<small>USD</small>':''}</span></button>`;}).join('')}</div><div class="section-info">${icon('info')} Optional accessories are priced for ${model().name}. An optical scale request is listed separately and is excluded from the calculated total until a price is confirmed.</div></section>`;}
function customerScreen(){return`<section class="section-panel"><div class="section-label">03 / CUSTOMER DETAILS</div><h2 class="section-title">Let’s make it yours.</h2><p class="section-description">A few details, and your personalized quotation is ready.</p>${modelStrip()}<form id="customer-form"><div class="form-grid"><label class="field"><span>Full name <span class="required">*</span></span><input name="name" autocomplete="name" placeholder="Your full name" value="${esc(state.details.name)}" maxlength="180" required></label><label class="field"><span>Email address <span class="required">*</span></span><input type="email" name="email" autocomplete="email" placeholder="you@company.com" value="${esc(state.details.email)}" maxlength="180" required></label><label class="field full"><span>Company name <span style="color:#73828d;font-weight:400">(optional)</span></span><input name="company" autocomplete="organization" placeholder="Your company or organization" value="${esc(state.details.company)}" maxlength="180"></label><label class="field full"><span>Project notes <span style="color:#73828d;font-weight:400">(optional)</span></span><textarea name="notes" placeholder="Tell us about your materials, application, or any specific requirements…" rows="4" maxlength="2400">${esc(state.details.notes)}</textarea><small>Include any requirements you would like reflected in your quotation.</small></label></div><button type="submit" hidden>Review quotation</button></form><div class="form-privacy">${icon('lock')}<div><strong>Prepared for your next move.</strong><p>Your details appear on your downloaded quotation. Nothing is sent when you review or download.</p></div></div></section>`;}
function reviewScreen(){const m=model(),t=totals(),dates=quoteDates();const items=selectedAccessories();return`<section class="section-panel"><div class="review-header"><div class="section-label">04 / REVIEW & DOWNLOAD</div>${icon('shield')}</div><h2 class="section-title">Your next chapter. On paper.</h2><p class="section-description">Review your configuration, then download your complete quotation as a PDF.</p><article class="quote-document" aria-label="Quotation preview"><div class="quote-doc-heading"><div class="quote-doc-brand">NANYA <span>CNC</span><small>CNC MACHINE QUOTATION</small></div><div class="quote-id"><strong>${dates.id}</strong>Issued ${dates.date}<br>Valid until ${dates.valid}</div></div><div class="quote-customer"><div><span class="doc-label">PREPARED FOR</span><strong>${esc(state.details.name)}</strong>${state.details.company?`<p>${esc(state.details.company)}</p>`:''}<p>${esc(state.details.email)}</p></div><div><span class="doc-label">PRICE BASIS</span><strong>FOB Shanghai sea-port</strong><p>All amounts in USD</p></div></div><div class="quote-model-row"><img src="${m.image}" alt="${m.name}"><div><span class="series">${m.series.toUpperCase()}</span><strong>${m.name}</strong><p>MITSUBISHI M80A · 12,000 RPM<br>${m.travel.join(' × ')} mm (X / Y / Z)</p></div></div><table class="quote-table"><thead><tr><th>CONFIGURATION</th><th>AMOUNT · USD</th></tr></thead><tbody><tr><td>${m.name} — CNC vertical machining center</td><td>${money(m.price)}</td></tr>${items.map(a=>`<tr><td>${esc(a.name)}</td><td>${accessoryPrice(a)===null?'On request':money(accessoryPrice(a))}</td></tr>`).join('')}${items.length?'':'<tr><td style="color:#8c9592">Optional accessories</td><td style="color:#8c9592">None selected</td></tr>'}<tr class="doc-total"><td>${t.onRequest?'Calculated total':'Quotation total'}</td><td>${money(t.total)}</td></tr></tbody></table>${t.onRequest?'<p class="doc-request">Optical scale pricing is on request and excluded from the calculated total. The final total is subject to that price being confirmed.</p>':''}${state.details.notes?`<div class="doc-notes"><span class="doc-label">PROJECT NOTES</span>${esc(state.details.notes)}</div>`:''}<div class="doc-terms"><span class="doc-label">TERMS & CONDITIONS</span><ol>${data.terms.map(term=>`<li>${esc(term)}</li>`).join('')}</ol></div><p class="doc-validity">Final pricing is confirmed in your quotation and is valid for 30 days from the issue date. The PDF also includes the complete machine specifications and standard accessories package.</p></article><div class="review-actions"><button data-action="step" data-step="3">${icon('edit')} Edit your details</button><button data-action="specs">View complete specifications ${icon('external')}</button></div></section>`;}
function ctaText(){return ['Continue to accessories','Continue to your details','Review your quotation','Download quotation PDF'][state.step-1];}
function renderSummary(){const m=model(),t=totals();$('#summary').innerHTML=`<div class="summary-label">${icon('file')} YOUR CONFIGURATION</div><div class="summary-title-row"><h2>Every detail. Yours.</h2><span class="live-tag"><i></i> LIVE</span></div><div class="summary-product"><img src="${m.image}" alt=""><div><strong>${m.name}</strong><span>${m.series}</span><button data-action="specs">Machine specifications ${icon('external')}</button></div></div><div class="summary-breakdown"><div class="price-line"><span>Machine base price</span><strong>${money(m.price)}</strong></div><div class="price-line"><span>Optional accessories</span><strong>${money(t.accessories)}</strong></div>${selectedAccessories().map(a=>`<div class="price-line accessory-line"><span>${esc(a.short)}</span><strong class="${accessoryPrice(a)===null?'request':''}">${accessoryPrice(a)===null?'On request':money(accessoryPrice(a))}</strong></div>`).join('')}${state.accessories.length?'':'<p class="summary-empty">A strong foundation. Add accessories in the next step to match your workflow.</p>'}<div class="total-block"><div class="total-label">${t.onRequest?'CALCULATED TOTAL':'YOUR QUOTATION TOTAL'}<span>FOB SHANGHAI</span></div><div class="total-amount">${money(t.total)}<small>USD</small></div><p class="total-disclaimer">${t.onRequest?'Excludes items priced on request.':'Machine + selected accessories.'}<br>Quotation valid for 30 days from issue.</p></div></div>${t.onRequest?'<div class="request-note">Optical scale pricing requires confirmation and is excluded from this total.</div>':''}<button class="primary-button desktop-cta" data-action="continue">${ctaText()}${icon(state.step===4?'download':'arrow')}</button><div class="summary-footnote">${icon('lock')} ${state.step===4?'Prepared instantly. Download directly.':'Your configuration, saved as you go.'}</div>${state.step>1?`<button class="summary-back" data-action="back">${icon('left')} Back to ${stepNames[state.step-2].toLowerCase()}</button>`:''}<div class="assurances"><div>${icon('delivery')}<span><strong>55–60 days</strong><small>Delivery from down payment</small></span></div><div>${icon('shield')}<span><strong>24 months</strong><small>From manufacturing date</small></span></div></div><div class="payment-strip"><span>PAYMENT SCHEDULE</span><div class="payment-flow"><div><strong>30%</strong><small>ADVANCE</small></div><span>→</span><div><strong>60%</strong><small>BEFORE SHIPMENT</small></div><span>→</span><div><strong>10%</strong><small>UPON SATISFACTION</small></div></div></div>`;
 $('#mobile-bar').innerHTML=`<div class="mobile-total"><small>${t.onRequest?'CALCULATED TOTAL':'QUOTATION TOTAL'}</small><strong>${money(t.total)}</strong><span>USD${t.onRequest?' + on request':''}</span></div><button class="primary-button" data-action="continue">${state.step===1?'Continue to accessories':state.step===2?'Your details':state.step===3?'Review quotation':'Download PDF'}${icon(state.step===4?'download':'arrow')}</button>`;
}
function validDetails(report=false){if(state.step===3){const form=$('#customer-form');for(const input of form.elements){if(input.name==='name')input.setCustomValidity(input.value.trim()?'':'Please enter your full name.');}if(report)return form.reportValidity();return form.checkValidity();}return !!(state.details.name.trim()&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(state.details.email));}
function goStep(step){if(step>state.maxStep||step<1||step>4)return;if(step===4&&!validDetails()){toast('Please complete your name and email address first.');return;}state.step=step;render();$('#stepper').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
async function proceed(){if(state.step===4){await downloadQuote();return;}if(state.step===3&&!validDetails(true))return;state.step++;state.maxStep=Math.max(state.step,state.maxStep);save();render();$('#stepper').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function selectMachine(id){if(!data.models.some(m=>m.id===id))return;state.machine=id;save();render();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function setupProductMotion(){const stage=$('.machine-stage');const image=$('.stage-product img');if(matchMedia('(prefers-reduced-motion: reduce)').matches||!matchMedia('(pointer:fine)').matches)return;stage.addEventListener('pointermove',e=>{if(state.view!=='product')return;const r=stage.getBoundingClientRect();const x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;image.style.animation='none';image.style.transform=`perspective(1000px) rotateY(${x*5}deg) rotateX(${-y*3}deg) translate(${x*7}px,${y*4}px)`;});stage.addEventListener('pointerleave',()=>image.style.transform='');}
function setupScene(){sceneController=mountStage($('.studio-stage'),model(),{onExpand:openExplorer,onView:view=>state.view=view});}
function openExplorer(){openDialog(model().name+' / Machine explorer',stageHTML(model(),'3d',{expanded:true}));$('#dialog').classList.add('explorer-dialog');sceneController?.pause(true);modalSceneController=mountStage($('#dialog .studio-stage'),model());}
function openIntro(){if($('#dialog').open)$('#dialog').close();sceneController?.pause(true);showSplash(model(),{onClose:()=>sceneController?.pause(false)});}
function openDialog(title,body){modalSceneController?.dispose();modalSceneController=null;$('#dialog').classList.remove('explorer-dialog');$('#dialog-content').innerHTML=`<div class="dialog-top"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function openSpecs(id=state.machine,tab='specs'){modalMachine=id;modalTab=tab;const m=data.models.find(m=>m.id===id);const body=tab==='specs'?`<div class="spec-sections">${m.specs.map(s=>`<section class="spec-section"><h4>${s.title.toUpperCase()}</h4>${s.rows.map(([k,v])=>`<div class="spec-row"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</section>`).join('')}</div>`:tab==='included'?`<div class="included-list">${data.included.map(a=>`<div>${icon('check')}${esc(a)}</div>`).join('')}</div>`:termsContent();openDialog('Machine specifications',`<div class="dialog-product"><img src="${m.image}" alt="${m.name}"><div><div class="section-label">${m.series.toUpperCase()}</div><h3>${m.name}</h3><p>${m.description}</p><div class="price">${money(m.price)} <span style="font-size:10px;color:#94a0a9;font-weight:400">USD · base price</span></div></div></div><div class="spec-tabs" role="group" aria-label="Specification sections">${[['specs','Technical specifications'],['included','Standard accessories'],['terms','Terms & conditions']].map(([id,name])=>`<button data-action="spec-tab" data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div>${body}`);}
function termsContent(){return`<ol class="terms-list">${data.terms.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="terms-callout">Final pricing is confirmed in your quotation and is valid for 30 days from the issue date. Amounts are in USD. Items marked “On request” are excluded from the calculated total until confirmed.</div>`;}
function openCompare(){const rows=[['Base price',m=>money(m.price)],['Series',m=>m.series],['X / Y / Z travel',m=>m.travel.join(' / ')+' mm'],['Table size',m=>m.table],['Table load',m=>m.load],['Spindle',()=> '12,000 RPM'],['Control',()=> 'MITSUBISHI M80A'],['Tool magazine',()=> '24 tools'],['Machine weight',m=>m.weight]];openDialog('Seven machines. Your perfect fit.',`<p class="section-description">Compare the original machine specifications, then select the right fit for your work.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>THE LINEUP</th>${data.models.map(m=>`<th class="${m.id===state.machine?'is-current':''}"><img src="${m.image}" alt="">${m.name}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th>${label}</th>${data.models.map(m=>`<td class="${m.id===state.machine?'is-current':''}">${esc(fn(m))}</td>`).join('')}</tr>`).join('')}<tr><th>Your next move</th>${data.models.map(m=>`<td><button data-action="compare-select" data-machine="${m.id}">${m.id===state.machine?'Selected ✓':'Select '+m.name}</button></td>`).join('')}</tr></tbody></table></div>`);}
async function downloadQuote(){if(pdfBusy)return;pdfBusy=true;const buttons=document.querySelectorAll('[data-action="continue"]');buttons.forEach(b=>{b.disabled=true;b.dataset.label=b.innerHTML;b.textContent='Preparing your PDF…';});try{const {buildQuotation}=await import('./quotation-pdf.js');const bytes=await buildQuotation({model:model(),accessories:selectedAccessories().map(a=>({...a,price:accessoryPrice(a)})),totals:totals(),details:state.details,dates:quoteDates(),terms:data.terms,included:data.included});if(preparedPdfUrl)URL.revokeObjectURL(preparedPdfUrl);preparedPdfUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));let a=$('#prepared-download');if(!a){a=document.createElement('a');a.id='prepared-download';a.className='prepared-download';$('.review-actions').after(a);}a.href=preparedPdfUrl,modalSceneController;a.download=`NANYA-${model().name}-Quotation.pdf`;a.innerHTML=icon('download')+' Save prepared PDF';a.click();toast('Your PDF is ready. You can also use “Save prepared PDF” below the preview.');}catch(e){console.error('PDF generation:',e);toast('The PDF could not be prepared. Please try downloading again.');}finally{pdfBusy=false;buttons.forEach(b=>{b.disabled=false;b.innerHTML=b.dataset.label;});}}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled||!data)return;const action=button.dataset.action;if(action==='intro')return openIntro();if(action==='continue')return proceed();if(action==='step')return goStep(Number(button.dataset.step));if(action==='back')return goStep(state.step-1);if(action==='machine')return selectMachine(button.dataset.machine);if(action==='accessory'){const id=button.dataset.accessory;state.accessories=state.accessories.includes(id)?state.accessories.filter(v=>v!==id):[...state.accessories,id];save();renderMain();renderSummary();return;}if(action==='filter'){state.filter=button.dataset.filter;renderMain();return;}if(action==='view'){state.view=button.dataset.view;renderMain();return;}if(action==='scroll-left'||action==='scroll-right'){$('#machine-list').scrollBy({left:(action==='scroll-right'?1:-1)*$('#machine-list').clientWidth*.7,behavior:'smooth'});return;}if(action==='specs')return openSpecs();if(action==='spec-tab')return openSpecs(modalMachine,button.dataset.tab);if(action==='compare')return openCompare();if(action==='compare-select'){selectMachine(button.dataset.machine);$('#dialog').close();return;}if(action==='close')return $('#dialog').close();if(action==='terms')return openDialog('Quotation terms & conditions',termsContent());if(action==='help')return openDialog('From possibility to production.',`<div class="help-grid">${[['01','Find your machine','Explore seven CNC machining centers. Compare travel, table load, dimensions, and complete specifications.'],['02','Configure your capabilities','Select the accessories your application needs. Pricing updates instantly for the chosen model.'],['03','Make it personal','Add your name, email, company and project requirements to personalize the quotation.'],['04','Take the next step','Review and download your quotation PDF, including technical specifications and the standard accessories package.']].map(([n,title,text])=>`<div class="help-card"><span>${n} /</span><h3>${title}</h3><p>${text}</p></div>`).join('')}</div><div class="terms-callout">Need the commercial details? Review the quotation terms for delivery, warranty, payment schedule and FOB pricing.</div>`);if(action==='reset')return openDialog('Start a new configuration?',`<div class="reset-body"><p>This clears your current machine options and customer details so you can build a new quotation.</p><div class="reset-actions"><button class="secondary-button" data-action="close">Keep current quotation</button><button class="primary-button" data-action="confirm-reset">Start fresh</button></div></div>`);if(action==='confirm-reset'){state={machine:'nv-1270',accessories:[],step:1,maxStep:1,filter:'all',view:'3d',details:{name:'',email:'',company:'',notes:''}};save();render();$('#dialog').close();toast('A fresh configuration, ready for you.');return;}if(action.startsWith('scene-')&&sceneController){if(action==='scene-rotate'){const running=sceneController.toggleRotate();button.classList.toggle('active',!running);button.setAttribute('aria-label',running?'Pause automatic rotation':'Start automatic rotation');}if(action==='scene-wire'){button.classList.toggle('active',sceneController.toggleWire());}if(action==='scene-zoom-in')sceneController.zoom(-1);if(action==='scene-zoom-out')sceneController.zoom(1);if(action==='scene-reset')sceneController.reset();}});
document.addEventListener('input',e=>{if(!e.target.closest('#customer-form'))return;const name=e.target.name;if(Object.hasOwn(state.details,name)){state.details[name]=e.target.value;if(name==='name')e.target.setCustomValidity('');save();}});
document.addEventListener('submit',e=>{if(e.target.id==='customer-form'){e.preventDefault();proceed();}});
$('#studio-link').addEventListener('click',e=>{e.preventDefault();goStep(1);});$('.brand').addEventListener('click',e=>{e.preventDefault();if(data)goStep(1);});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});

$('#dialog').addEventListener('close',()=>{modalSceneController?.dispose();modalSceneController=null;$('#dialog').classList.remove('explorer-dialog');sceneController?.pause(!!document.querySelector('#studio-splash[open]'));});
